	public enum Flag
	{
		/** The monster rolls magic defence off its Defence level rather than its Magic level. */
		MAGIC_USES_DEFENCE,
		/** In CoX the monster's Magic level scales with the defensive party-size factor, not the offensive one. */
		COX_MAGIC_IS_DEFENSIVE,
		/** A Chambers of Xeric monster, so its levels take the party-size and Challenge Mode scaling. */
		COX_SCALED,
		/** Takes a smaller Challenge Mode defensive bump than the rest of CoX (Tekton). */
		COX_CM_SMALL_DEFENCE_BUMP,
		/** A boss in The Fractured Archive (Raids 4). */
		TFA,
		/** A demon, so the arclight family drains it harder. */
		DEMON
	}

	private final String npcName;
	private final int baseDef;
	private final int baseMagic;
	private final int baseAtk;
	private final int baseStr;
	private final int baseMagicDef;
	private final int minDef;
	private final Set<Flag> flags;

	BossDefence(String npcName, int baseDef, int baseMagic, int baseAtk, int baseStr, int baseMagicDef, int minDef,
		Flag... flags)
	{
		this.npcName = npcName;
		this.baseDef = baseDef;
		this.baseMagic = baseMagic;
		this.baseAtk = baseAtk;
		this.baseStr = baseStr;
		this.baseMagicDef = baseMagicDef;
		this.minDef = minDef;
		this.flags = flags.length == 0 ? EnumSet.noneOf(Flag.class) : EnumSet.copyOf(Arrays.asList(flags));
	}

	public boolean has(Flag flag)
	{
		return flags.contains(flag);
	}

	/**
	 * Phase-specific and same-name actor identification must use the real NPC
	 * rather than rendered visibility or the NPC name alone. In particular,
	 * both Dagon'hai monks have independent Defence pools, and the Ocellus
	 * hooded NPC and unverified noncombat forms must not acquire combat stats.
	 */
	public static BossDefence matchingNpc(NPC npc)
	{
		if (npc == null || npc.getName() == null)
		{
			return null;
		}
		String name = Text.removeTags(npc.getName()).trim();
		if ("Dagon'hai Monk".equalsIgnoreCase(name))
		{
			if (npc.getId() == 16645)
			{
				return TFA_DAGONHAI_MONK_16645;
			}
			if (npc.getId() == 16646)
			{
				return TFA_DAGONHAI_MONK_16646;
			}
			return null; // Unknown monk actors must not share either monk's state.
		}
		// The Blade world NPC (including the repaired version, 16683) is a prop.
		// Combat specs land on the attackable Ocellus actor, never on the prop.
		if ("The Blade".equalsIgnoreCase(name))
		{
			return null;
		}
		if ("Ocellus".equalsIgnoreCase(name))
		{
			// 16675 is a transition-only actor, not a Defence target.
			// Keep it out of the P3 combat-level fallback too.
			if (npc.getId() == 16675)
			{
				return null;
			}
			// Only confirmed P2 combat actor 16676 can own the P2 pool.
			if (npc.getId() == 16676)
			{
				return TFA_OCELLUS_P2;
			}
			// Wiki infobox and later combat-level corrections disagree between
			// 1197 and 1601. Both distinguish the combat P3 NPC from P1 (1121).
			if (npc.getCombatLevel() == 1197 || npc.getCombatLevel() == 1601)
			{
				return TFA_OCELLUS_P3;
			}
			if (npc.getId() == 16673 || npc.getId() == 16674)
			{
				return TFA_OCELLUS_P1;
			}
			return null; // Unknown or non-combat hooded forms: fail closed.
		}
		return matchingNpcName(name);
	}

	/**
	 * This exact NPC ID is the confirmed attackable P2 Ocellus target.
	 * Do not depend on the transformed composition's Attack option: it may
	 * be absent during NPC updates, despite the actor being damageable.
	 * Transition actor 16675 and the Blade prop 16683 are always excluded.
	 */
	static boolean isAttackableOcellusPhaseTwo(NPC npc)
	{
		return npc != null && npc.getId() == 16676 && npc.getName() != null
			&& "Ocellus".equalsIgnoreCase(Text.removeTags(npc.getName()).trim());
	}

	/**
	 * Zero health ratio can also mean 'no health bar yet'. Do not treat an
	 * confirmed P2 actor as dead solely because its ratio is unavailable.
	 * Never make this exception for the P1/P3 or transition-only actors.
	 */
	static boolean isLiveNpc(NPC npc)
	{
		return npc != null && !npc.isDead()
			&& (npc.getHealthRatio() != 0 || isAttackableOcellusPhaseTwo(npc));
	}

	/**
	 * Name-only matching for other callers. Ambiguous TFA names intentionally
	 * require {@link #matchingNpc(NPC)} so no monk or Ocellus phase is guessed.
	 */
	public static BossDefence matchingNpcName(String name)
	{
		if (name == null || name.trim().isEmpty())
		{
			return null;
		}
		String trimmed = Text.removeTags(name).trim();
		if ("The Blade".equalsIgnoreCase(trimmed))
		{
			return null; // Props are never tracked by name.
		}
		for (BossDefence boss : values())
		{
			String candidate = Text.removeTags(boss.npcName).trim();
			if (candidate.equalsIgnoreCase(trimmed))
			{
				return boss;
			}
		}
		for (BossDefence boss : values())
		{
			String candidate = Text.removeTags(boss.npcName).trim();
			if (trimmed.regionMatches(true, 0, candidate, 0, candidate.length())
				&& trimmed.length() > candidate.length()
				&& trimmed.charAt(candidate.length()) == ' ')
			{
				return boss;
			}
		}
		return null;
	}
}

package net.betterpartydefence;

import net.runelite.api.gameval.NpcID;

/**
 * Optional per-boss lifecycle rules layered over the generic defence tracker.
 *
 * <p>The default profile deliberately preserves the tracker behaviour used by existing bosses.
 * Bosses only opt in here when their NPC actor lifecycle does not map cleanly to an encounter
 * lifecycle (for example, Kephri temporarily reaching 0 HP between shield phases).</p>
 */
enum BossMechanics
{
	STANDARD(false),
	KEPHRI(true)
	{
		@Override
		boolean preserveStateAtZeroHp(int npcId)
		{
			// Shielded/weak Kephri can sit at 0 HP while the same encounter continues.
			// The final enrage actor is intentionally excluded so its death remains terminal.
			return npcId == NpcID.TOA_KEPHRI_BOSS_SHIELDED
				|| npcId == NpcID.TOA_KEPHRI_BOSS_WEAK;
		}

		@Override
		boolean resetsStatsOnActorEntry(int npcId)
		{
			return npcId == NpcID.TOA_KEPHRI_BOSS_ENRAGE;
		}

		@Override
		boolean endsEncounterOnActorEntry(int npcId)
		{
			return npcId == NpcID.TOA_KEPHRI_BOSS_DEAD;
		}
	},
	SOTETSEG(true),
	/**
	 * Boss actor changes/temporary zero-health during phases are not a raid reset.
	 * P3 Ocellus must retain reductions over every quadrant (21 Oct hotfix).
	 * Guard the live state until the authoritative raid exit/new-attempt reset.
	 */
	TFA_PHASE_PERSISTENT(true)
	{
		@Override
		boolean preserveStateAtZeroHp(int npcId)
		{
			return true;
		}
	};

	private final boolean phasePersistent;

	BossMechanics(boolean phasePersistent)
	{
		this.phasePersistent = phasePersistent;
	}

	boolean isPhasePersistent()
	{
		return phasePersistent;
	}

	boolean preserveStateAtZeroHp(int npcId)
	{
		return false;
	}

	boolean resetsStatsOnActorEntry(int npcId)
	{
		return false;
	}

	boolean endsEncounterOnActorEntry(int npcId)
	{
		return false;
	}

	static BossMechanics forBoss(BossDefence boss)
	{
		if (boss == BossDefence.KEPHRI)
		{
			return KEPHRI;
		}
		if (boss == BossDefence.SOTETSEG)
		{
			return SOTETSEG;
		}
		if (boss == BossDefence.TFA_ARCHIVE_GUARDIAN
			|| boss == BossDefence.TFA_XARTH
			|| boss == BossDefence.TFA_OCELLUS_P1
			|| boss == BossDefence.TFA_OCELLUS_P2
			|| boss == BossDefence.TFA_OCELLUS_P3)
		{
			return TFA_PHASE_PERSISTENT;
		}
		return STANDARD;
	}
}

