	{
		int npcIndex;
		String bossName;
		BossDefence bossType;
		int bossNpcId;
		boolean kephriFinalResetApplied;
		int sotetsegEncounterState;
		long bossDef;
		long bossStartDef;
		long minDef;
		long atkLevel;
		long strLevel;
		long magicLevel;
