package net.betterpartydefence;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the tracked NPC's Defence in scene space. */
public class NpcDefenceOverlay extends Overlay
{
	private final Client client;
	private final DefenceTracker tracker;
	private final BetterPartyDefenceConfig config;
	private final TrackerFontManager fontManager;
	private final DefenceOverlayRenderer renderer;
	private final PreviousTargetDisplayState previousTargetState;
	private final InitialSyncDisplayGate initialSyncDisplayGate;

	public NpcDefenceOverlay(Client client, DefenceTracker tracker, BetterPartyDefenceConfig config,
		SkillIconSource skillIcons, TrackerFontManager fontManager,
		PreviousTargetDisplayState previousTargetState, InitialSyncDisplayGate initialSyncDisplayGate)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.fontManager = fontManager;
		this.renderer = new DefenceOverlayRenderer(config, skillIcons);
		this.previousTargetState = previousTargetState;
		this.initialSyncDisplayGate = initialSyncDisplayGate;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.defenceHpBar())
		{
			return null;
		}

		graphics.setFont(fontManager.font());
		DefenceState current = tracker.state();
		List<DefenceState> states = tracker.states();

		if (!config.previousTargetDisplay())
		{
			renderLegacyAttached(graphics, states);
			return null;
		}

		renderMainTarget(graphics, current);

		DefenceState previous = previousTargetState.previousState();
		if (previous != null && !initialSyncDisplayGate.isWaiting(previous, client.getTickCount()))
		{
			NPC npc = liveNpc(previous.getNpcIndex());
			if (npc != null)
			{
				renderAtNpc(graphics, previous, npc,
					config.defenceHpBarPosition(), config.defenceHpBarYOffset());
			}
		}
		return null;
	}

	/** Exact pre-feature attached rendering path, used whenever the experiment is disabled. */
	private void renderLegacyAttached(Graphics2D graphics, List<DefenceState> states)
	{
		DefenceOverlayPosition position = config.defenceHpBarPosition();
		for (DefenceState state : states)
		{
			if (!isDisplayable(state))
			{
				continue;
			}
			NPC npc = liveNpc(state.getNpcIndex());
			if (npc != null)
			{
				renderAtNpc(graphics, state, npc, position, config.defenceHpBarYOffset());
			}
		}
	}

	private void renderMainTarget(Graphics2D graphics, DefenceState current)
	{
		if (!isDisplayable(current))
		{
			return;
		}
		NPC npc = liveNpc(current.getNpcIndex());
		if (npc != null)
		{
			renderAtNpc(graphics, current, npc,
				config.defenceHpBarPosition(), config.defenceHpBarYOffset());
		}
	}

	private void renderAtNpc(Graphics2D graphics, DefenceState state, NPC npc,
		DefenceOverlayPosition position, int yOffset)
	{
		int zOffset = (int) (npc.getLogicalHeight() * position.getHeightFactor()) + position.getHeightOffset();
		Point anchor = npc.getCanvasTextLocation(graphics, "", zOffset);
		if (anchor == null)
		{
			return;
		}
		int centreX = anchor.getX() + position.getXNudge();
		int baseline = anchor.getY() - yOffset;
		renderer.renderAt(graphics, state, centreX, baseline);
	}

	private boolean isDisplayable(DefenceState state)
	{
		// The checkbox controls only optional pre-spec preview. Any actual local/party drain
		// remains displayable because drained=true is part of the stored/shared state.
		return state != null && (state.isDrained() || config.defenceAlwaysShow())
			&& state.getNpcIndex() >= 0
			&& !initialSyncDisplayGate.isWaiting(state, client.getTickCount());
	}

	private NPC liveNpc(int index)
	{
		if (index < 0 || client.getTopLevelWorldView() == null || client.getTopLevelWorldView().npcs() == null)
		{
			return null;
		}
		NPC npc = client.getTopLevelWorldView().npcs().byIndex(index);
		return BossDefence.isLiveNpc(npc) ? npc : null;
	}
}

package net.betterpartydefence;

import java.util.List;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.runelite.api.Client;
import net.runelite.api.NPC;

/**
 * Rendering-only memory for the experimental previous-target display.
 *
 * <p>This never mutates DefenceTracker state. It only remembers which already-tracked target was
 * active immediately before the current one, and only exposes it while that concrete NPC is still
 * live in this client's scene.
 */
final class PreviousTargetDisplayState
{
	private final Client client;
	private final DefenceTracker tracker;
	private final BetterPartyDefenceConfig config;

	private boolean trackingActive;
	private int lastActiveNpcIndex = -1;
	private BossDefence lastActiveBoss;
	private Integer previousTargetNpcIndex;

	PreviousTargetDisplayState(Client client, DefenceTracker tracker, BetterPartyDefenceConfig config)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
	}

	void update()
	{
		DefenceState current = tracker.state();
		List<DefenceState> states = tracker.states();

		if (!config.defenceHpBar() || !config.previousTargetDisplay())
		{
			reset(current);
			return;
		}

		if (!trackingActive)
		{
			trackingActive = true;
			lastActiveNpcIndex = boundIndex(current);
			lastActiveBoss = lastActiveNpcIndex >= 0 ? tracker.trackedBossType() : null;
			previousTargetNpcIndex = null;
			return;
		}

		if (states.isEmpty())
		{
			clear();
			return;
		}

		int currentIndex = boundIndex(current);
		BossDefence currentBoss = current == null ? null : tracker.trackedBossType();

		// Sotetseg's combat/maze actor replacements belong to one logical encounter and its
		// Defence is intentionally restored by DefenceTracker at each maze. Never let those
		// actor swaps enter the experimental previous-target display, otherwise a stale pre-maze
		// snapshot can appear beside the authoritative current Sotetseg state.
		if (currentBoss == BossDefence.SOTETSEG || lastActiveBoss == BossDefence.SOTETSEG)
		{
			previousTargetNpcIndex = null;
			lastActiveNpcIndex = currentIndex;
			lastActiveBoss = currentBoss;
			return;
		}

		if (currentIndex < 0 || currentIndex == lastActiveNpcIndex)
		{
			if (stateByIndex(states, previousTargetNpcIndex) == null)
			{
				previousTargetNpcIndex = null;
			}
			return;
		}

		DefenceState prior = stateByIndex(states, lastActiveNpcIndex);
		NPC priorNpc = prior == null ? null : liveNpc(prior.getNpcIndex());

		// Actor replacement for the same logical boss (phase/rebind/render churn) is not a user
		// target switch. It must not manufacture a sticky copy of the current encounter.
		boolean sameLogicalRebind = prior != null && lastActiveBoss == currentBoss && priorNpc == null;
		if (!sameLogicalRebind && prior != null && prior.isDrained())
		{
			previousTargetNpcIndex = prior.getNpcIndex();
		}
		else if (prior == null || sameLogicalRebind)
		{
			previousTargetNpcIndex = null;
		}

		lastActiveNpcIndex = currentIndex;
		lastActiveBoss = currentBoss;
		if (previousTargetNpcIndex != null && previousTargetNpcIndex == currentIndex)
		{
			previousTargetNpcIndex = null;
		}
	}

	DefenceState previousState()
	{
		if (!config.defenceHpBar() || !config.previousTargetDisplay())
		{
			return null;
		}
		DefenceState previous = stateByIndex(tracker.states(), previousTargetNpcIndex);
		DefenceState current = tracker.state();
		if (previous == null || !previous.isDrained()
			|| (current != null && previous.getNpcIndex() == current.getNpcIndex()))
		{
			return null;
		}
		return liveNpc(previous.getNpcIndex()) == null ? null : previous;
	}

	void clear()
	{
		trackingActive = false;
		lastActiveNpcIndex = -1;
		lastActiveBoss = null;
		previousTargetNpcIndex = null;
	}

	private void reset(DefenceState current)
	{
		trackingActive = false;
		lastActiveNpcIndex = boundIndex(current);
		lastActiveBoss = lastActiveNpcIndex >= 0 ? tracker.trackedBossType() : null;
		previousTargetNpcIndex = null;
	}

	private static int boundIndex(DefenceState state)
	{
		return state == null ? -1 : state.getNpcIndex();
	}

	private static DefenceState stateByIndex(List<DefenceState> states, Integer index)
	{
		if (index == null || index < 0)
		{
			return null;
		}
		for (DefenceState state : states)
		{
			if (state != null && state.getNpcIndex() == index)
			{
				return state;
			}
		}
		return null;
	}

	private NPC liveNpc(int index)
	{
		if (index < 0 || client.getTopLevelWorldView() == null || client.getTopLevelWorldView().npcs() == null)
		{
			return null;
		}
		NPC npc = client.getTopLevelWorldView().npcs().byIndex(index);
		return npc != null && !npc.isDead() && npc.getHealthRatio() != 0 ? npc : null;
	}
}

package net.betterpartydefence;

import java.util.List;

/**
 * Resolve the two delayed Tonalztics of Ralos glaive hits from game-client
 * hitsplat arrival order. Both normal damage and misses (0) count as
 * hitsplats. Later same-tick thrall/Vengeance/instant-damage hitsplats
 * cannot overwrite the pair, regardless of whether thrall models render.
 *
 * Evidence: RuneLite SpecialCounterPlugin, upstream PR #20377 merged Oct 20,
 * 2026. Arrival order: [delayed hits, thrall, veng, instant hits].
 *
 * This is NOT general-purpose attribution of multiple distinct delayed
 * projectiles arriving on the same tick; no attacker ID exists on hitsplats.
 */
final class RalosHitResolver
{
    static final int UNKNOWN = -1;

    private RalosHitResolver() {}

    /** Return 0..2 successful glaives, or UNKNOWN if the pair is incomplete. */
    static int countConfirmedHits(List<Integer> orderedHitsplats)
    {
        if (orderedHitsplats == null || orderedHitsplats.size() < 2)
        {
            return UNKNOWN;
        }
        Integer first = orderedHitsplats.get(0);
        Integer second = orderedHitsplats.get(1);
        if (first == null || second == null || first < 0 || second < 0)
        {
            return UNKNOWN;
        }
        return (first > 0 ? 1 : 0) + (second > 0 ? 1 : 0);
    }
}

